    incoming: !!c.incoming, private: !!c.private, source: c.private ? 2 : 0,
    user_id: c.incoming ? t.requester.id : AGENT.id,
    from_email: c.incoming ? t.requester.email : AGENT.email,
    created_at: c.at || iso(c.min)
  };
}
function ticketOut(t, withDetail) {
  const out = {
    id: t.id, subject: t.subject, description_text: t.convos[0] ? t.convos[0].text : '',
    priority: t.priority, status: t.status, type: t.type, source: 2, tags: t.tags,
    requester_id: t.requester.id, responder_id: AGENT.id, company_id: t.company.id, group: t.group,
    due_by: iso(t.due), fr_due_by: iso(t.frDue), is_escalated: false, fr_escalated: false,
    created_at: iso(t.created), updated_at: iso(t.convos.length ? (t.convos[t.convos.length - 1].min || 0) : 0),
    stats: { first_responded_at: t.firstRespAt || (t.firstResp != null ? iso(t.firstResp) : null), resolved_at: null }
  };
  if (withDetail) {
    out.requester = t.requester;
    out.company = t.company;
    out.conversations = t.convos.map((c, i) => convoOut(t, c, i));
  }
  return out;
}

function respond(status, payload, type) {
  return [{ json: { status, contentType: type || 'application/json', body: typeof payload === 'string' ? payload : JSON.stringify(payload) } }];
}

const req = $input.first().json;
const q = req.query || {};
const body = req.body || {};
const op = String(q.op || 'list');

if (!sd.db || op === 'reset') sd.db = seed();
const db = sd.db;
if (op === 'reset') return respond(200, { reset: true });
if (op === 'console') return respond(200, CONSOLE_HTML, 'text/html; charset=utf-8');
if (op === 'list') return respond(200, db.tickets.map(t => ticketOut(t, false)));

const t = db.tickets.find(x => String(x.id) === String(q.id));
if (!t) return respond(404, { description: 'Resource not found', id: q.id });

if (op === 'ticket') return respond(200, ticketOut(t, true));

if (op === 'note' || op === 'reply') {
  const html = String(body.body || '');
  if (!html) return respond(400, { description: 'Validation failed', errors: [{ field: 'body', message: 'Mandatory attribute missing' }] });
  const c = { at: new Date().toISOString(), incoming: false, private: op === 'note', text: stripHtml(html), html };
  t.convos.push(c);
  if (op === 'reply' && !t.firstResp && !t.firstRespAt) t.firstRespAt = c.at;
  return respond(201, convoOut(t, c, t.convos.length - 1));
}

if (op === 'update') {
  if (Array.isArray(body.tags)) t.tags = body.tags.map(String);
  if (Number.isInteger(body.priority)) t.priority = body.priority;
  return respond(200, ticketOut(t, false));
}

return respond(400, { description: 'Unknown op', op });
